#!/usr/bin/env python3
"""Optional maintenance tool: refresh ready-to-host HTML from centralized configuration."""
import json, html, pathlib, math
ROOT=pathlib.Path(__file__).resolve().parents[1]
c=json.loads((ROOT/'data/config.json').read_text()); b=c['business']; E=html.escape
pages=[('', 'Home'),('services','Services'),('areas','Service Areas'),('pricing','Pricing'),('about','About'),('contact','Contact'),('faq','FAQ'),('privacy','Privacy Policy')]
icons={'box':'M4 7 12 3 20 7 12 11Z M4 7v10l8 4 8-4V7 M12 11v10 M8 5l8 4','garage':'M3 10 12 3 21 10 M5 9v12h14V9 M8 21V12h8v9 M8 15h8 M8 18h8','stairs':'M3 21h18V3h-6v6H9v6H3Z','sofa':'M5 11V7a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v4 M5 17H3v-6h4v4h10v-4h4v6h-2 M5 17h14v3 M5 17v3','washer':'M5 3h14v18H5Z M5 7h14 M8 5h1 M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8','leaf':'M20 3C8 2 2 8 5 15s16 6 15-12Z M4 21 16 9','tools':'m4 4 16 16 M4 20 20 4 M3 3h5v5 M16 16h5v5','building':'M5 21V3h14v18 M3 21h18 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M10 21v-6h4v6'}
def icon(n):return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+icons[n]+'"/></svg>'
def brand():return '<a class="brand" href="/" aria-label="Dual Duty Junk Removal home"><img src="/assets/logo-128.png" alt="" width="64" height="64"><span><strong>DUAL DUTY</strong><small>JUNK REMOVAL</small></span></a>'
def btn(url,text,secondary=False):return f'<a class="btn {"secondary" if secondary else ""}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def head(ey,title,desc):return f'<section class="page-heading"><div class="wrap"><span class="eyebrow">{ey}</span><h1>{title}</h1><p>{desc}</p></div></section>'
def section(content,alt=False):return '<section class="section'+(' alt' if alt else '')+'"><div class="wrap">'+content+'</div></section>'
def sh(ey,title,desc=''):return f'<div class="section-head"><div><span class="eyebrow">{ey}</span><h2>{title}</h2></div><p>{desc}</p></div>'
def cards(limit=None):
 s=[s for s in c['services'] if s['enabled']][:limit]
 return '<div class="grid service-list">'+''.join(f'<article class="card service" data-search="{E(x["title"]+" "+x["description"])}">{icon(x["icon"])}<span class="num">{i+1:02d} /</span><h3>{E(x["title"])}</h3><p>{E(x["description"])}</p><span class="badge">Planned for launch</span></article>' for i,x in enumerate(s))+'</div>'
def faq(limit=None):return '<div class="faq-list">'+''.join(f'<details data-search="{E(x["category"]+" "+x["question"]+" "+x["answer"])}"><summary><span class="faq-category">{E(x["category"])}</span>{E(x["question"])}</summary><p>{E(x["answer"])}</p></details>' for x in c['faqs'][:limit])+'</div><p class="no-results" hidden>No matching questions. Try “pricing”, “items”, or “launch”.</p>'
def map_svg():
 # Equirectangular projection at 39.4 N; true relative point positions, no invented boundary.
 scale=770; points=[]
 for i,a in enumerate(c['areas']):
  x=70+(a['lon']+111.9)*math.cos(math.radians(39.4))*scale;y=48+(39.67-a['lat'])*scale
  left=a['name'] in ['Fountain Green','Wales','Moroni','Fayette','Centerfield']
  dx=-13 if left else 13; anchor='end' if left else 'start'
  # Centerfield label is offset downward to separate it from nearby Gunnison.
  dy=16 if a['name']=='Centerfield' else 4
  points.append(f'<g class="map-point {"selected" if i==0 else ""}" data-town="{E(a["name"])}" role="button" tabindex="0" aria-label="Select {E(a["name"])}" aria-pressed="{"true" if i==0 else "false"}"><circle cx="{x:.2f}" cy="{y:.2f}" r="9" fill="#147E83" stroke="#F7FAF9" stroke-width="5"/><circle cx="{x:.2f}" cy="{y:.2f}" r="22" fill="transparent" style="fill:transparent;stroke:none"/><text x="{x+dx:.2f}" y="{y+dy:.2f}" text-anchor="{anchor}" fill="#18364A" font-family="Arial,sans-serif" font-size="12">{E(a["name"])}</text></g>')
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 520" aria-labelledby="map-title map-desc"><title id="map-title">Planned Sanpete communities</title><desc id="map-desc">Geographically positioned community markers, not service boundaries. Use the community buttons below as an alternative.</desc><defs><pattern id="map-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#147E83" stroke-opacity=".12"/></pattern></defs><rect width="520" height="520" fill="#D9E9E5"/><rect width="520" height="520" fill="url(#map-grid)"/><text x="25" y="32" fill="#18364A" font-family="monospace" font-size="12">N ↑</text><text x="295" y="495" fill="#526871" font-size="10" font-family="monospace">COMMUNITY LOCATIONS / UT</text>'+''.join(points)+'</svg>'
(ROOT/'assets/communities.svg').write_text(map_svg())
def area_block():return '<div class="split"><div class="map-box">'+map_svg()+'<p class="map-note">Approximate community locations. No service boundaries or routes implied. <a class="textlink" href="/areas/#sources">Map sources ↗</a></p></div><div><span class="eyebrow">Rooted right here</span><h2>Small towns.<br>Big plans.</h2><p>Based in Spring City. Planning to serve our neighbors across Sanpete County, including surrounding rural communities.</p><div class="selection" aria-live="polite"><h3 id="town-title">Spring City · Home base</h3><p id="town-description">Planned coverage. Service has not launched; exact address availability and travel charges will require confirmation.</p></div><div class="towns">'+''.join(f'<button type="button" data-town="{E(a["name"])}" aria-pressed="{"true" if i==0 else "false"}">{E(a["name"])}</button>' for i,a in enumerate(c['areas']))+'</div><p class="micro">Outside a listed town? Rural Sanpete jobs will be reviewed individually once inquiries open.</p></div></div>'
def cta():return '<div class="cta"><div><span class="eyebrow">A little planning goes a long way</span><h2>Picture your space. Minus the junk.</h2><p>Build a load plan now. Get a confirmed quote when we launch.</p></div>'+btn('/pricing/#planner','Estimate your load')+'</div>'
steps='<div class="grid steps">'+''.join(f'<article class="step"><span class="step-num">0{i+1} ───</span><h3>{t}</h3><p>{p}</p></article>' for i,(t,p) in enumerate([('Tell us what goes.','Start with the load planner. Add your items and flag anything that needs extra care.'),('Get a clear estimate.','When inquiries open, we’ll review the details and confirm the scope and price with you.'),('Make room for more.','Schedule removal once services launch and your job has been approved.')]))+'</div>'
values='<div class="values">'+''.join(f'<div class="value"><b>0{i+1}</b><div><h3>{t}</h3><p>{p}</p></div></div>' for i,(t,p) in enumerate([('Local roots. Real people.','Two local founders building a practical service for the place we call home.'),('Straight answers, from the start.','Clear scope and transparent estimates are the plan. No invented prices or surprise promises.'),('Hands-on by design.','Both founders intend to share the physical work. Small team. Shared responsibility.'),('A thoughtful next stop.','We aim to consider reuse and appropriate disposal where facilities and item condition allow.')]))+'</div>'
planner='''<div class="calculator" id="planner"><div class="calc-main"><span class="eyebrow">01 / Build your load</span><h3>What needs to go?</h3><p class="micro">Add items, then adjust quantities and estimated volume per item. Default volumes are rough planning assumptions.</p><div class="calc-tabs" id="categories"></div><div class="catalog" id="catalog"></div><div class="item-row row-head"><span>ITEM</span><span>QTY</span><span>YD³ EACH</span><span></span></div><div id="selected-items"><p>Add an item to begin your plan.</p></div><div class="calc-controls"><span class="eyebrow">02 / The job details</span><div class="two"><div class="field"><label for="difficulty">Loading difficulty</label><select id="difficulty"><option value="easy">Easy — curb or driveway</option><option value="moderate">Moderate — indoor carry</option><option value="difficult">Difficult — tight / long carry</option></select></div><div class="field"><label for="stairs">Flights of stairs</label><input id="stairs" type="number" min="0" max="10" step="1" value="0"></div></div><div class="field"><label for="city">Service community</label><select id="city"></select></div><label class="check"><input id="special" type="checkbox">Special disposal requirements</label><p class="micro">Do not include hazardous materials. Appliance and heavy-item acceptance must be confirmed.</p><details><summary>Adjust total volume instead</summary><label class="check"><input id="use-volume" type="checkbox">Use my total volume instead of the item total</label><div class="field"><label for="manual-volume">Estimated occupied volume (cubic yards)</label><input type="number" id="manual-volume" min="0" max="100" step="0.1" value="0"></div><p class="micro">This replaces, rather than adds to, the item volume. Selected items still identify handling requirements.</p></details></div></div><aside class="calc-summary" aria-label="Your load plan"><h3>YOUR LOAD, AT A GLANCE</h3><div id="volume-output" class="volume-number" aria-live="polite">0.0 <small>yd³</small></div><div class="load-meter" aria-hidden="true"><span id="meter-fill" style="width:0%"></span></div><p id="load-label" class="micro">Add items to estimate occupied space.</p><div id="summary-items" class="summary-items">No items selected.</div><p id="summary-city" class="micro"></p><ul id="factors"></ul><p id="price" class="price">Rates not configured</p><p class="micro" id="price-note">Volume and complexity only. No dollar estimate is available.</p><p class="micro">Planning aid, not a quote or booking. Sizes, packing, weight limits, acceptance, and final pricing require business confirmation. Volume does not establish safe towing capacity.</p><div class="actions"><button class="btn" id="copy-plan" type="button">Copy plan</button><button class="btn secondary" id="download-plan" type="button">Download</button></div><button class="plain-button" id="print-plan" type="button">Print summary</button> · <button class="plain-button" id="clear-plan" type="button">Clear saved plan</button><p class="calc-status" id="calc-status" role="status"></p><p class="micro">Saved on this browser only. No personal information is requested or sent.</p></aside></div>'''
content={}
content['']='''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><div class="hero-stamp"><img class="hero-mark" src="/assets/logo-128.png" alt="" width="54" height="54"><span class="dot"></span> LOCAL FOUNDERS. GETTING READY.</div><h1>YOUR JUNK.<br><span>OUR DUTY.</span></h1><p>Locally founded junk removal serving Sanpete County, Utah. A fresh start for your space is on the way.</p><div class="actions">'''+btn('/services/','Explore our services')+btn('/pricing/#planner','Estimate your load',True)+'''</div><p class="micro">PRE-LAUNCH · NOT ACCEPTING BOOKINGS YET</p></div><div class="hero-art"><img src="/assets/rig.svg" alt="Custom illustration of a teal pickup and hauling trailer against mountain silhouettes" width="900" height="650" fetchpriority="high"><span class="art-caption">BRAND ILLUSTRATION · NOT ACTUAL EQUIPMENT</span></div></div></section><div class="wrap stats"><div class="stat"><strong>2</strong><span>LOCAL FOUNDERS<br>One shared responsibility.</span></div><div class="stat"><strong>13</strong><span>SANPETE COMMUNITIES<br>In our planned coverage.</span></div><div class="stat"><strong>1</strong><span>SIMPLE MISSION<br>Clear the clutter.</span></div></div>'''+section(sh('Less clutter. More possibility.','A clean slate starts here.','From the sofa that’s overstayed its welcome to a garage ready for a comeback. Here’s what we’re planning.')+cards(6)+'<a class="textlink" href="/services/">Explore all planned services →</a>',True)+section('<div class="split"><div class="brand-panel"><span class="eyebrow">The Dual Duty difference</span><h2>Two founders.<br>Both sleeves<br>rolled up.</h2><p>We’re building a local business around a simple idea: show up prepared, communicate clearly, and do useful work.</p><div class="big-outline" aria-hidden="true">ALL IN.</div><a class="textlink" style="color:white" href="/about/">Meet the idea behind Dual Duty ↗</a></div>'+values+'</div>')+section(sh('No runaround','A simpler way to clear space.','Our planned process. Estimates and scheduling will open when we’re ready to operate.')+steps,True)+section(area_block())+section('<div class="split"><div><span class="eyebrow">Know your load</span><h2>Big pile?<br>Let’s size it up.</h2><p>Build an item-by-item plan in a few taps. See estimated volume, flag stairs and heavy items, and save a summary for later.</p>'+btn('/pricing/#planner','Open the load planner')+'<p class="micro" style="margin-top:18px">No made-up prices. No contact details needed.</p></div><div class="card"><span class="eyebrow">Interactive load planner</span><h3>Start with what you see.</h3>'+icon('sofa')+'<p>A sofa, a few boxes, the old dresser… add each item to get a clearer picture of your load.</p><div class="two" style="margin-top:24px"><div class="field"><label for="quick-item">Try an item</label><select id="quick-item"><option value="sofa">Sofa</option><option value="mattress">Mattress</option><option value="boxes">Box</option><option value="washer">Washing machine</option></select></div><div class="field"><label for="quick-quantity">Quantity</label><input id="quick-quantity" type="number" min="1" max="99" step="1" value="1"></div></div><p id="quick-result" aria-live="polite">Open the planner to estimate your load.</p><a id="quick-open" class="textlink" href="/pricing/?starter=sofa#planner">Continue in the load planner →</a><p class="micro">Editable item sizes · On-device saving · Copy & download</p></div></div>',True)+section(sh('Good questions. Straight answers.','Before you clear it out.')+faq(5)+'<a class="textlink" href="/faq/">All questions & answers →</a>')+section(cta())
content['services']=head('Planned services','New space.<br>New possibilities.','Practical junk removal for the stuff you’re ready to part with. All services below are planned and subject to confirmation before launch.')+section('<label class="field search">Find a planned service<input id="service-search" type="search" placeholder="Try furniture, garage, or yard"></label>'+cards()+'<p class="no-results" hidden>No matching services. Try a broader term.</p>')+section(sh('Know before you load','Some things need a specialist.','These materials are excluded from the planned offering.')+'<div class="notice">'+', '.join(E(x) for x in c['restrictedMaterials'])+'.</div><p>We do not offer demolition, utility disconnection, hazardous waste disposal, or specialized industrial services. Pianos, safes, hot tubs, concrete, and unusually heavy items need individual review and may be declined.</p>'+btn('/pricing/','Plan an eligible load'),True)
content['areas']=head('Spring City based / County minded','Your neighborhood.<br>Our home turf.','Planned junk removal coverage across Sanpete County, Utah. Select a community to explore; no location is open for bookings yet.')+section(area_block())+section('<div class="prose" id="sources"><span class="eyebrow">About this map</span><h2>Real places. Clear limits.</h2><p>Markers use approximate community coordinates projected at 39.4° north. This is a location diagram, not a county boundary, route map, or guarantee of address-level availability. No travel times or road distances are inferred.</p><details><summary>Coordinate sources and attribution</summary><ul>'+''.join(f'<li><a href="{E(a["source"])}" target="_blank" rel="noopener noreferrer">{E(a["name"])} coordinate source</a> — {a["lat"]:.4f}, {a["lon"]:.4f}</li>' for a in c['areas'])+'</ul><p>Source coordinates checked October 18, 2026. TopoZone reports USGS place coordinates; other linked providers are identified at each source. Mapcarta credits OpenStreetMap and GeoNames. Original visualization by Dual Duty.</p></details></div>',True)
content['pricing']=head('Less guesswork / More clarity','Size up your load.<br>Skip the surprises.','Our rates are still being finalized. Use this planner to estimate space and job complexity now, with no personal details and no invented prices.')+section('<div class="notice">Pre-launch planning tool. Item volumes are approximate; actual trailer capacity and payload limits are not yet confirmed.</div><noscript><p class="notice">The interactive load planner needs JavaScript. You can still review all pricing factors below. No rates have been configured.</p></noscript>'+planner)+section(sh('What shapes a quote','It’s more than the size of the pile.')+'<div class="grid">'+''.join(f'<article class="card"><h3>{t}</h3><p>{d}</p></article>' for t,d in [('Space & material','Volume is a starting point. Dense debris may reach safe weight limits before filling the available space.'),('Access & labor','Stairs, long carries, narrow doors, and loading difficulty can change the people and time a job needs.'),('Travel & disposal','Your location, facility fees, and any approved special handling affect the final scope and cost.')])+'</div>',True)
content['about']=head('Local roots. Shared duty.','Built here.<br>For the space ahead.','Two local founders. One practical idea: help our neighbors clear out what’s in the way.')+section('<div class="split"><div class="brand-panel">'+brand()+'<span class="eyebrow">Our starting point</span><h2>Good work starts<br>with showing up.</h2><p>A local operation taking shape in Spring City, with a pickup, access to a hauling trailer, and a plan to share the work.</p><div class="big-outline" aria-hidden="true">2 → 1</div></div><div class="prose"><h2>Two roles.<br>One responsibility.</h2><p>One founder brings the technical and website side. The other brings access to the hauling equipment. Both intend to split the job effort equally.</p><p>We’re still in the planning stage: deciding what we can safely take, confirming disposal arrangements, and putting the practical details in place before accepting work.</p><p>That means being clear about what’s ready and what isn’t. No invented track record. No promises we haven’t earned. Just a local team building something useful.</p></div></div>')+section(values,True)+section(cta())
fields=[('Customer name','text','name'),('Email','email','email'),('Phone','tel','phone'),('City','text','city-preview'),('Service address','text','address'),('Preferred date','date','date')]
form='<form class="form-preview" aria-label="Future quote request preview"><h3>Plan today. Reach out soon.</h3><p>This is a preview of our future request form. All fields are disabled. No information or photos can be submitted.</p><fieldset disabled><legend>Online requests coming soon</legend><div class="two">'+''.join(f'<div class="field"><label for="preview-{i}">{t}</label><input id="preview-{i}" type="{typ}" autocomplete="off" disabled></div>' for t,typ,i in fields)+'</div><div class="field"><label for="preview-description">Description of junk</label><textarea id="preview-description" rows="3" disabled></textarea></div><div class="field"><label for="preview-photos">Photos</label><input id="preview-photos" type="file" accept="image/*" multiple disabled></div><div class="field"><label for="preview-notes">Additional notes</label><textarea id="preview-notes" rows="3" disabled></textarea></div><button type="button" class="btn" disabled>Requests aren’t open yet</button></fieldset></form>'
contact='<dl class="contact-details">'+''.join(f'<dt>{t}</dt><dd id="contact-{k}">{E(b.get(k) or "To be announced")}</dd>' for t,k in [('Phone','phone'),('Email','email'),('Hours','hours')])+'<dt>Social media</dt><dd id="contact-socials">Links will appear when available</dd><dt>Operating base</dt><dd>'+E(b['base'])+' · No public drop-off location</dd></dl>'
content['contact']=head('Not quite on the road yet','Good things<br>are on the way.','Dual Duty is getting ready to launch. Contact details and inquiry availability will appear here when they’re confirmed.')+section('<div class="contact-grid"><div><span class="eyebrow">Current status</span><h2>Pre-launch.<br>Plans in progress.</h2><p>We’re not taking bookings, accepting payments, or collecting customer information through this website.</p>'+contact+btn('/pricing/','Build a load plan')+'<div id="integration-links"></div></div>'+form+'</div>')
content['faq']=head('The details matter','Ask away.<br>We’ll keep it straight.','What’s planned, what’s confirmed, and what we’re still working out.')+section('<label class="field search">Search questions<input id="faq-search" type="search" placeholder="Try pricing, stairs, or payment"></label><p id="search-count" class="micro" role="status"></p>'+faq())
content['privacy']=head('Transparency, including online','Privacy policy.<br>The working draft.','Draft · October 18, 2026. Describes this pre-launch static website. Not legally reviewed or a compliance certification.')+section('''<article class="prose"><h2>What this website does</h2><p>Dual Duty Junk Removal is a pre-launch local business based in Spring City, Utah. The website describes planned services and provides a browser-based load planner. It does not currently accept quote requests, bookings, payments, or photo uploads.</p><h2>Calculator storage on your device</h2><p>The planner saves selected catalog items, quantities, editable volumes, loading difficulty, stair count, service community, and a special-handling flag in this browser’s localStorage under <code>dualDuty.plan.v1</code>. It does not request names, street addresses, contact details, dates, free-text notes, or photos. Data remains until you choose “Clear saved plan” or clear this site’s browser data. It is not sent to the business. Other users of the same browser profile may be able to see it.</p><h2>Information we do not collect through forms</h2><p>The contact form is a disabled preview. Fields cannot be edited, files cannot be selected, and no form submissions are made. The website includes no advertising trackers, analytics scripts, third-party fonts, or tracking cookies.</p><h2>Hosting and technical requests</h2><p>Your browser requests website files from the hosting provider. Hosting providers may process technical information such as IP addresses, request times, and browser details for delivery, security, and operations. For the intended GitHub Pages deployment, consult <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" rel="noopener noreferrer" target="_blank">GitHub’s privacy statement</a>. Hosting preview environments may have their own policies.</p><h2>Copying, downloading, and printing</h2><p>These actions happen on your device. Copying writes the non-personal plan summary to your clipboard only when you request it. Downloaded or printed copies are under your control. Clearing the planner does not remove downloaded files or clipboard contents.</p><h2>External links</h2><p>Map source links and documentation may lead to other websites. Those websites operate under their own policies. No external map tiles or geographic APIs load automatically.</p><h2>Future changes</h2><p>Before adding customer requests, scheduling, payment services, or analytics, this policy must be updated to identify providers, data collected, purposes, retention practices, and available privacy controls. Existing feature switches do not activate data collection by themselves.</p><h2>Questions</h2><p>Business contact information is not yet configured. A privacy contact method will be provided on the <a href="/contact/">contact page</a> before the business begins collecting customer information online.</p></article>''')
content['404']=head('404 / Wrong turn','This load<br>went missing.','That page isn’t here. Let’s get you back on the right road.')+section(btn('/','Back to home')+' '+btn('/services/','Explore services',True))
descs={'':'Pre-launch junk removal in Sanpete County, Utah. Meet Dual Duty, explore planned services, and estimate your load without sharing personal details.','services':'Explore planned household junk removal, garage cleanouts, furniture and yard debris services in Sanpete County. Dual Duty is preparing to launch.','areas':'Explore Dual Duty’s planned Sanpete County coverage, based in Spring City, including Ephraim, Manti, Mount Pleasant and surrounding communities.','pricing':'Estimate junk volume and loading complexity with the Dual Duty load planner. Company prices are not configured; final quotes require confirmation.','about':'Meet the idea behind Dual Duty Junk Removal: a two-founder, locally operated startup preparing to serve Sanpete County from Spring City, Utah.','contact':'Dual Duty Junk Removal is pre-launch. Contact details and online requests are coming soon. No bookings, payments, or personal data submissions are available.','faq':'Find answers about planned junk removal services, materials, pricing, coverage, scheduling, and policies still being finalized by Dual Duty.','privacy':'Draft privacy policy for Dual Duty’s static website and browser-local load planner. No active customer forms, payments, analytics, or tracking cookies.','404':'Page not found. Return to Dual Duty Junk Removal.'}
for slug,label in pages+[('404','Page not found')]:
 title=('Junk Removal Sanpete County, Utah' if not slug else label)+' | '+b['name'];url=b['domain']+('/' if not slug else '/'+slug+'/')
 nav=''.join(f'<a href="/{s+"/" if s else ""}"'+(' aria-current="page"' if s==slug else '')+f'>{l}</a>' for s,l in pages[1:6])
